choose.otherwise:
SELECT
(
    SELECT count(1)
    FROM tb_user_notice
    WHERE user_id = #{userId}
    AND notice_type != 'system'
) + (
    SELECT count(1)
    FROM tb_system_notice
)

mapper.select:
SELECT * FROM (
SELECT id, user_id AS userId, notice_type AS noticeType, source_id AS sourceId, source_type AS sourceType, target_id AS targetId, target_type AS targetType, jump_path AS jumpPath, anchor_key AS anchorKey, content, CASE WHEN notice_type IN ('comment_reply', 'talk_reply') THEN reply_content ELSE NULL END AS replyContent, is_read AS isRead, create_time AS createTime FROM tb_user_notice WHERE user_id = #{userId}
AND notice_type = #{noticeQueryVO.noticeType}
AND notice_type != 'system'
UNION ALL
SELECT sn.id, #{userId} AS userId, 'system' AS noticeType, NULL AS sourceId, 'system' AS sourceType, NULL AS targetId, 'system' AS targetType, sn.jump_path AS jumpPath, NULL AS anchorKey, sn.content, NULL AS replyContent, CASE WHEN snr.id IS NULL THEN 0 ELSE 1 END AS isRead, sn.create_time AS createTime FROM tb_system_notice sn LEFT JOIN tb_system_notice_read snr ON snr.notice_id = sn.id AND snr.user_id = #{userId}
) notice_list ORDER BY createTime DESC, id DESC LIMIT #{limitCurrent}, #{size}

SELECT
(
    SELECT count(1)
    FROM tb_user_notice
    WHERE user_id = #{userId}
    AND is_read = 0
    AND notice_type != 'system'
) + (
    SELECT count(1)
    FROM tb_system_notice sn
    LEFT JOIN tb_system_notice_read snr ON snr.notice_id = sn.id AND snr.user_id = #{userId}
    WHERE snr.id IS NULL
)
